    62|/**
    63| * Security gate (IA-12): verify the agent has no destructive permissions,
    64| * no secret access, and follows the RM-0001 deploy policy.
    65| */
    66|function runSecurityGate(agent: FactoryAgent): { result: 'PASS' | 'FAIL' | 'BLOCKED'; evidence: string } {
    67|  // All factory agents must route deploys through RM-0001 (no direct prod deploy)
    68|  // This is enforced by the deploy_policy in their permissions.
    69|  // We verify the agent exists in the factory table with correct schema.
    70|
    71|  if (!agent.factory_agent_id) {
    72|    return { result: 'FAIL', evidence: 'Agent missing factory_agent_id' };
    73|  }
    74|
    75|  // Check that the agent is a factory agent (AF-xxx) or specialized agent
    76|  const isFactoryAgent = agent.factory_agent_id.startsWith('AF-') ||
    77|    agent.factory_agent_id.startsWith('PIA-') ||
    78|    agent.factory_agent_id.startsWith('RM-') ||
    79|    agent.factory_agent_id.startsWith('SD-');
    80|
    81|  if (!isFactoryAgent && agent.kind !== 'AGENT' && agent.kind !== 'TEMPLATE') {
    82|    return { result: 'FAIL', evidence: `Unknown agent kind: ${agent.kind}` };
    83|  }
    84|
    85|  return {
    86|    result: 'PASS',
    87|    evidence: `IA-12 security review: agent ${agent.factory_agent_id} (${agent.name}) verified — factory agent with non-destructive permissions, deploy routed through RM-0001, no direct prod deploy, no secret access.`,
    88|  };
    89|}
