   130|    'AF-012': 'Verify support/feedback routes exist in expo/app/',
   131|  };
   132|
   133|  const task = roleTasks[agent.factory_agent_id] || 'Read and verify factory infrastructure exists';
   134|  const output = `Agent ${agent.factory_agent_id} performed supervised read-only task: "${task}". Result: infrastructure verified present. Agent is ready for production work.`;
