   139|async function restCall(path: string, init: RequestInit = {}): Promise<{ status: number | null; body: string }> {
   140|  const base = supabaseUrl();
   141|  const key = serviceRoleKey();
   142|  if (!base || !key) return { status: null, body: 'supabase credentials missing' };
   143|  try {
   144|    const response = await fetch(`${base}${path}`, {
   145|      ...init,
   146|      headers: {
   147|        apikey: key,
   148|        Authorization: `Bearer ${key}`,
   149|        'Content-Type': 'application/json',
   150|        ...(init.headers ?? {}),
   151|      },
   152|      signal: AbortSignal.timeout(10_000),
   153|    });
   154|    return { status: response.status, body: (await response.text()).slice(0, 10_000) };
   155|  } catch (error: unknown) {
   156|    return { status: null, body: error instanceof Error ? error.message.slice(0, 200) : 'fetch failed' };
   157|  }
