   172|async function verifyAndActivateAgent(agent: FactoryAgent): Promise<VerificationResult> {
   173|  const now = new Date().toISOString();
   174|  const security = runSecurityGate(agent);
   175|  const qa = runQaGate(agent);
   176|  const work = await performSupervisedWork(agent);
   177|
   178|  const status: VerificationResult['status'] =
   179|    security.result === 'PASS' && qa.result === 'PASS' ? 'VERIFIED'
   180|    : security.result === 'BLOCKED' || qa.result === 'BLOCKED' ? 'BLOCKED'
   181|    : 'FAILED';
   182|
   183|  let activatedAt: string | null = null;
   184|
   185|  if (status === 'VERIFIED') {
   186|    // Activate the agent in Supabase
   187|    const activateRes = await restCall(
   188|      `/rest/v1/ivx_ia_factory_agents?factory_agent_id=eq.${agent.factory_agent_id}`,
   189|      {
   190|        method: 'PATCH',
   191|        body: JSON.stringify({
   192|          activation_status: 'ACTIVE',
   193|          qa_status: 'PASSED',
   194|          updated_at: now,
   195|        }),
   196|      },
   197|    );
   198|
   199|    if (activateRes.status === 200 || activateRes.status === 204) {
   200|      activatedAt = now;
   201|    } else {
   202|      // Activation failed — don't claim success
   203|      return {
   204|        agentId: agent.factory_agent_id,
   205|        agentName: agent.name,
   206|        role: agent.kind,
   207|        realTask: work.output,
   208|        input: `Verify agent ${agent.factory_agent_id}`,
   209|        output: `Activation failed: HTTP ${activateRes.status}`,
   210|        toolsUsed: work.toolsUsed,
   211|        securityResult: security.result,
   212|        qaResult: qa.result,
   213|        status: 'BLOCKED',
   214|        evidence: `Security: ${security.evidence}. QA: ${qa.evidence}. Activation failed: ${activateRes.body.slice(0, 200)}`,
   215|        activatedAt: null,
   216|      };
   217|    }
   218|  }
   219|
   220|  // Update the verification task status
   221|  const verifyTaskId = `AF-VERIFY-${agent.factory_agent_id.split('-')[1]}`;
   222|  await restCall(
   223|    `/rest/v1/ivx_ia_tasks?task_id=eq.${verifyTaskId}`,
   224|    {
   225|      method: 'PATCH',
   226|      body: JSON.stringify({
   227|        status: status === 'VERIFIED' ? 'VERIFIED' : 'BLOCKED',
   228|        evidence: `Security: ${security.evidence}. QA: ${qa.evidence}. Work: ${work.output}. Activated: ${activatedAt ?? 'not activated'}.`,
   229|        updated_at: now,
   230|      }),
   231|    },
   232|  );
   233|
   234|  return {
   235|    agentId: agent.factory_agent_id,
   236|    agentName: agent.name,
   237|    role: agent.kind,
   238|    realTask: work.output,
   239|    input: `Verify agent ${agent.factory_agent_id} (${agent.name})`,
   240|    output: status === 'VERIFIED' ? `Agent activated at ${activatedAt}` : `Agent not activated: ${status}`,
   241|    toolsUsed: work.toolsUsed,
   242|    securityResult: security.result,
   243|    qaResult: qa.result,
   244|    status,
   245|    evidence: `Security: ${security.evidence}. QA: ${qa.evidence}. Work: ${work.output}. Activated: ${activatedAt ?? 'not activated'}.`,
   246|    activatedAt,
   247|  };
